import csv, collections as C, statistics as S
from datetime import datetime as D
def read(n):return list(csv.DictReader(open('data/'+n+'.csv')))
inc,act,staff=map(read,['incidents','activity','staffing'])
a={r['incident_id']:r for r in act}
assert len(inc)==len({r['incident_id'] for r in inc}) and len(a)==len(act) and a.keys()<={r['incident_id'] for r in inc}
W=['manual','assist']
for r in inc:
 r.update(a.get(r['incident_id'],{})); r['date']=r['opened_at'][:10]
 assert r['workflow']==W[r['date']>='2026-06-08']
 if r.get('closed_at'):
  r['t']=(D.fromisoformat(r['closed_at'])-D.fromisoformat(r['opened_at'])).total_seconds()/60
  assert r['t']>=0 and r['closed_at']<='2026-06-22T23:59:00Z'
  for k in ['responder_minutes','handoffs','reopened_within_72h']:r[k]=int(r[k])
 r['cap']=min(r.get('t',10080),10080)
def grp(rows,*ks):
 g=C.defaultdict(list)
 for r in rows:g[tuple(r[k] for k in ks)].append(r)
 return dict(sorted(g.items()))
def st(rs):
 cs=[r for r in rs if 't' in r]
 def m(k):return S.mean(r[k] for r in cs) if cs else float('nan')
 return [len(rs),len(cs),round(S.median(r['t'] for r in cs),1) if cs else None,*[round(m(k),2) for k in ('t','responder_minutes','handoffs','reopened_within_72h')],round(S.mean(r['cap'] for r in rs),2),sum(r['t']<=1440 for r in cs),sum(r['t']<=10080 for r in cs),sum(r['responder_minutes'] for r in cs)]
print('N closed median_t mean_t mean_minutes mean_handoffs reopen restricted_t closed24 closed7 sum_minutes')
for ks in [('workflow',),('severity','workflow'),('intake_channel','workflow'),('service_group','workflow'),('service_group','severity','intake_channel','workflow'),('date',)]:
 for k,v in grp(inc,*ks).items():print(k,st(v))
 print()
print('missing',[(r['incident_id'],r['workflow'],r['severity'],r['service_group'],r['intake_channel']) for r in inc if 't' not in r])
print('latest close',max(r['closed_at'] for r in act))
print('staff',[(k,[sum(int(r[f]) for r in v) for f in ['active_responders','scheduled_responder_hours','interruption_minutes','incidents_opened']]) for k,v in grp([dict(r,w=W[r['date']>='2026-06-08']) for r in staff],'w').items()])
