def compare(ks):
 g=grp(inc,*ks,'workflow')
 keys={k[:-1] for k in g}
 pairs=[(g[k+('manual',)],g[k+('assist',)]) for k in sorted(keys) if k+('assist',) in g and k+('manual',) in g]
 cp=[([r for r in m if 't' in r],[r for r in b if 't' in r]) for m,b in pairs]
 print('compare',ks)
 for k in ('cap','closed24'):
  def v(r):return r[k] if k=='cap' else int(r.get('t',1e9)<=1440)
  n=sum(len(b) for m,b in pairs)
  print(k, n, [sum(len(b)*S.mean(map(v,rs)) for m,b in pairs for rs in [m if j==0 else b])/n for j in (0,1)])
 for k in ('t','responder_minutes','handoffs','reopened_within_72h'):
  match=[(m,b) for m,b in cp if m and b]
  n=sum(len(b) for m,b in match)
  base=sum(len(b)*S.mean(r[k] for r in m) for m,b in match)
  obs=sum(r[k] for m,b in match for r in b)
  print(k,n,base/n,obs/n,(obs-base)/60 if k=='responder_minutes' else '')
 manual_prediction=sum(len(b)*S.mean(r.get('responder_minutes',0) for r in m) for m,b in pairs)
 assist_total=sum(r.get('responder_minutes',0) for m,b in pairs for r in b)
 print('zero fill both',manual_prediction,assist_total,(assist_total-manual_prediction)/60)
 print('bench full staffed cases',sum(len(b)*S.mean(r['responder_minutes'] for r in m if 't' in r) for m,b in pairs))
for ks in [('severity',),('severity','service_group'),('severity','service_group','intake_channel')]:compare(ks)
counts=C.Counter((r['date'],r['service_group']) for r in inc)
assert all(counts[r['date'],r['service_group']]==int(r['incidents_opened']) for r in staff)
for ks in [('workflow',),('severity','workflow')]:
 for k,rs in grp(inc,*ks).items(): print('all median',k,S.median(r['cap'] for r in rs))
for k,rs in grp(inc,'severity','workflow').items():
 print(k,'minutes min/max',min(r['responder_minutes'] for r in rs if 't' in r),max(r['responder_minutes'] for r in rs if 't' in r))
